function empleadoCtrl($scope,empleadoSvc,tS){$scope.empleados=[],$scope.resultModal=function(result){"object"==typeof result&&$scope.getEmpleados()},$scope.getEmpleados=function(){try{showLoader(),empleadoSvc.getAll({}).then(response=>{hideLoader(),$scope.empleados=response,$scope.totalRecords=response[0].totalRecords}).catch(err=>{hideLoader(),console.log(err)})}catch(error){hideLoader(),console.log(error)}},$scope.getEmpleados(),$scope.pagechanged=function(){$scope.getEmpleados()},$scope.changePageSize=function(){$scope.pageIndex=1,$scope.getEmpleados()},$scope.askToDelete=async item=>{let{isConfirmed:isConfirmed}=await Swal.fire({icon:"warning",title:"",html:"<small>Esta seguro/a de eliminar este Empleado <b>"+item.nombreCompleto+"</b>?</small> ",showDenyButton:!0,confirmButtonText:"Si,eliminar!",denyButtonText:"No, cancelar!",allowOutsideClick:!1});isConfirmed&&(showLoader(),empleadoSvc.deleteEmployee(item.idEmpleado).then(response=>{hideLoader(),"0"==response.code&&tS.toastr("warning",response.message,response.titleSms),"1"==response.code&&(hideLoader(),tS.toastr("success",response.message,response.titleSms),$scope.getEmpleados())}).catch(err=>{hideLoader(),console.log(err)}))}}app.controller("empleadoCtrl",empleadoCtrl),empleadoCtrl.$inject=["$scope","empleadoService","toastService"];